const PB_KID = (() => { try { const k = new URLSearchParams(location.search).get('kid'); return k === 'girl' || k === 'boy' ? k : ''; } catch (e) { return ''; } })();
const PB_KID_CSS = ` .pbk-girl [data-who=girl], .pbk-boy [data-who=boy] { display: inline !important; } .pbk-girl [data-who=boy], .pbk-boy [data-who=girl] { display: none !important; }`;
function PbArt({ name, h = 120, style, lit }) {
  let s = PB_ART[name]; if (!s) return null;
  if (lit) s = s.replace(new RegExp('(data-f="' + lit + '"[^>]*?)fill="#fffdf7"'), '$1fill="#e4572e"');
  const m = /viewBox="[\d.-]+ [\d.-]+ ([\d.]+) ([\d.]+)"/.exec(s); const w = m ? h * (+m[1]) / (+m[2]) : h;
  return <span className={'pb-art' + (PB_KID ? ' pbk-' + PB_KID : '')} data-art={name} style={{display:'inline-block',lineHeight:0,width:w,height:h,flex:'0 0 auto',...style}} dangerouslySetInnerHTML={{__html: s.replace('<svg ', '<svg width="100%" height="100%" ')}}/>;
}
